import SwiftUI
import UIKit
import WebKit
@MainActor final class StudyBrowser:NSObject,ObservableObject,WKNavigationDelegate,WKUIDelegate {
 var views:[UUID:WKWebView]=[:];weak var store:StudyStore?;var activeTask:UUID?;var selectedAccount:UUID?
 func view(_ account:StudyAccount)->WKWebView {if let w=views[account.id]{return w};let config=WKWebViewConfiguration();config.websiteDataStore=WKWebsiteDataStore(forIdentifier:account.id);config.allowsInlineMediaPlayback=true;config.mediaTypesRequiringUserActionForPlayback=[.audio,.video];let w=WKWebView(frame:.zero,configuration:config);w.navigationDelegate=self;w.uiDelegate=self;w.allowsBackForwardNavigationGestures=true;views[account.id]=w;if let u=URL(string:account.entry){w.load(URLRequest(url:u))};return w}
 func pause(){if let id=selectedAccount,let w=views[id]{w.evaluateJavaScript("document.querySelectorAll('video,audio').forEach(v=>v.pause())",completionHandler:nil);if let task=activeTask,let t=store?.library.tasks.first(where:{$0.id==task && $0.account==id}){store?.updateTask(task,id,state:"已暂停",position:t.position,duration:t.duration)}};activeTask=nil}
 func load(_ url:String,_ account:StudyAccount){guard StudyStore.trusted(url,account.platform),let u=URL(string:url)else{store?.message="请输入本平台HTTPS地址";return};view(account).load(URLRequest(url:u))}
 func webView(_ webView:WKWebView,decidePolicyFor action:WKNavigationAction,decisionHandler:@escaping(WKNavigationActionPolicy)->Void){guard let a=store?.library.accounts.first(where:{views[$0.id]===webView}),let url=action.request.url?.absoluteString else{decisionHandler(.cancel);return};if StudyStore.trusted(url,a.platform)||url=="about:blank"{decisionHandler(.allow)}else{store?.message="外部链接未自动离开当前账号空间";decisionHandler(.cancel)}}
 func evaluate(_ resource:String,_ account:StudyAccount)async throws->[String:Any]{guard let url=Bundle.main.url(forResource:resource,withExtension:"js"),let current=view(account).url?.absoluteString,StudyStore.trusted(current,account.platform)else{throw StudyError.invalid("请先打开平台学习页面")};let js=try String(contentsOf:url,encoding:.utf8);let result=try await view(account).evaluateJavaScript(js);guard let text=result as? String,let data=text.data(using:.utf8),let object=try JSONSerialization.jsonObject(with:data) as? [String:Any] else{throw StudyError.invalid("页面读取失败")};return object}
 func tick(_ account:StudyAccount)async {guard let task=activeTask else{return};do{let v=try await evaluate("media",account);guard (v["duration"] as? Double ?? 0)>0 else{return};let state=v["playing"] as? Bool == true ? "进行中":v["ended"] as? Bool == true ? "待平台核对":"已暂停";store?.updateTask(task,account.id,state:state,position:v["position"] as? Double ?? 0,duration:v["duration"] as? Double ?? 0);if v["security"] as? Bool == true{store?.message="平台需要人工安全验证，请在学习页面完成"}}catch{}}
 func alert(_ title:String,_ text:String,confirm:Bool=false,completion:@escaping(Bool)->Void){let a=UIAlertController(title:title,message:text,preferredStyle:.alert);if confirm{a.addAction(UIAlertAction(title:"取消",style:.cancel){_ in completion(false)})};a.addAction(UIAlertAction(title:"确定",style:.default){_ in completion(true)});let controller=UIApplication.shared.connectedScenes.compactMap{$0 as? UIWindowScene}.flatMap{$0.windows}.first{$0.isKeyWindow}?.rootViewController;var top=controller;while let next=top?.presentedViewController{top=next};top?.present(a,animated:true)}
 func webView(_ webView:WKWebView,runJavaScriptAlertPanelWithMessage message:String,initiatedByFrame frame:WKFrameInfo,completionHandler:@escaping()->Void){alert("平台提示",message){_ in completionHandler()}}
 func webView(_ webView:WKWebView,runJavaScriptConfirmPanelWithMessage message:String,initiatedByFrame frame:WKFrameInfo,completionHandler:@escaping(Bool)->Void){alert("平台确认",message,confirm:true,completion:completionHandler)}
}
struct PlatformBrowser:UIViewRepresentable {let browser:StudyBrowser;let account:StudyAccount;func makeUIView(context:Context)->WKWebView{browser.view(account)};func updateUIView(_ view:WKWebView,context:Context){} }

